function onLoad() {
    //Type appropriate comment here, and begin script below
    executeRule();
    // 调用 Script Include
    function executeRule() {
        var ga = new GlideAjax('x_846092_tst_2405.DateRangeUtils');
        ga.addParam('sysparm_name', 'getDateRanges');
        ga.getXMLAnswer(return_response);

    }

    function return_response(response) {
		alert(response);alert("B");
        //var dateRanges = response.responseXML.documentElement.getAttribute('answer');alert("B");
        var dateRanges = JSON.parse(response);alert(dateRanges);
        //g_form.addInfoMessage('Begin Today: ' + dateRanges.beginToday);
        alert('Begin Today: ' + dateRanges.beginToday);
    }
